KEYS = {"Devices/Compressor": "Comp", "Devices/DischargeSequence": "Dsq", "Devices/Evaporator": "CG", "Devices/ExhaustFan": "EF", "Devices/LTU": "LTU", "Devices/Pump": "Motor", "Devices/SafetyRelay": "Relay", "Devices/SuctionSequence": "Seq", "Devices/Tank": "Tank", "Devices/Valve": "Valve"}


def part(devicePath):
	"""Device key of an instance (its UDT type / configured PLC part; '' = not a PLC device)."""
	p = str(devicePath or "").rstrip("/")
	if not p:
		return ""
	try:
		qvs = system.tag.readBlocking([p + ".TypeId", p + "/AIn.Enabled", p + "/AInRef.Enabled", p + "/DIn.Enabled"])
	except Exception:
		return ""
	t = str(qvs[0].value or "") if qvs[0].quality.isGood() else ""
	on = [bool(q.value) if q.quality.isGood() and q.value is not None else False for q in qvs[1:]]
	if t == "Devices/Sensor":
		return "AIn" if on[0] else ("AInRef" if on[1] else "")
	if t == "Devices/DiscreteInput":
		return "DIn" if on[2] else ""
	return KEYS.get(t, "")


# member roots inside a device (Interlock, a tank's LevelInput / DI_*)
SUBS = ["DI_HLCO", "DI_HiLevel", "DI_LoLo", "DI_OPL", "Fan 1", "Fan 2", "Fan 3", "Input", "Interlock", "LevelInput", "Temp", "Valves"]


def device(base):
	"""Device instance for a member root: <device>/Interlock, <tank>/LevelInput, <tank>/DI_HLCO ... -> the device."""
	base = str(base or "").rstrip("/")
	head, _, leaf = base.rpartition("/")
	return head if leaf in SUBS else base


def resolve(base, leaf, pax=None):
	"""PAX member for <base>/<leaf> (base = a device or one of its SUBS roots) of a mapped device, else None."""
	base = str(base or "").rstrip("/")
	dev = device(base)
	return member(dev, (base[len(dev) + 1:] + "/" + leaf) if dev != base else leaf, pax)


def configured(devicePath, rel, cache=None):
	"""False when the part behind a PAX member is disabled on this instance (no PLC object, e.g. HPR PressAIn)."""
	head = rel.split("/")[0]
	key = str(devicePath).rstrip("/") + "/" + head
	if cache is not None and key in cache:
		return cache[key]
	try:
		qv = system.tag.readBlocking([key + ".Enabled"])[0]
		ok = (not qv.quality.isGood()) or qv.value is None or bool(qv.value)
	except Exception:
		ok = True
	if cache is not None:
		cache[key] = ok
	return ok


def mapRows(rows):
	"""Overview table rows (cells = '<device>/<field>' member paths): mapped devices read their PAX members."""
	out = []
	cache = {}
	for r in rows or []:
		try:
			row = dict(r)
		except Exception:
			out.append(r)
			continue
		dev = str(row.get("tagPath") or "")
		pax = part(dev) if dev else ""
		if pax:
			for k, v in row.items():
				if k != "tagPath" and str(v) == dev + "/" + k:
					p = member(dev, k, pax)
					if p:
						row[k] = ("pax:" + p) if configured(dev, p[len(dev) + 1:], cache) else ""
		out.append(row)
	return out


def livePath(path, cache=None):
	"""'<device>/<field>/Value' of a PLC-mapped device -> its PAX member (else the path itself) - for scripts that read
	device fields by literal path (shared.Forms live values)."""
	p = str(path or "")
	if not p.endswith("/Value"):
		return p
	base, _, leaf = p[:-len("/Value")].rpartition("/")
	if not base:
		return p
	dev = device(base)
	if cache is not None and dev in cache:
		pax = cache[dev]
	else:
		pax = part(dev)
		if cache is not None:
			cache[dev] = pax
	return (resolve(base, leaf, pax) or p) if pax else p


def member(devicePath, field, pax=None):
	"""PAX member path for an old field of a mapped device, else None."""
	pax = part(devicePath) if pax is None else pax
	rel = FIELDS.get(pax, {}).get(field)
	return (str(devicePath).rstrip("/") + "/" + rel) if rel else None
